package de.lazytv.pro.catalog; public class StreamItem implements java.io.Serializable { public final String id,name,categoryId,logo,streamUrl,tvgId; public final java.util.List<String> fallbackUrls; public final CatalogType type; public StreamItem(String id,String name,String categoryId,String logo,String streamUrl,String tvgId,CatalogType type){this(id,name,categoryId,logo,streamUrl,tvgId,type,java.util.Collections.emptyList());} public StreamItem(String id,String name,String categoryId,String logo,String streamUrl,String tvgId,CatalogType type,java.util.List<String> fallbackUrls){this.id=id;this.name=name;this.categoryId=categoryId;this.logo=logo;this.streamUrl=streamUrl;this.tvgId=tvgId;this.type=type;this.fallbackUrls=fallbackUrls==null?java.util.Collections.emptyList():java.util.Collections.unmodifiableList(new java.util.ArrayList<>(fallbackUrls));} }